<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\SoftDeletes;
class GuiaInternaDetalle extends Model{use SoftDeletes;protected $fillable=['guia_interna_id','restaurant_id','item_id','item_tipo','item_codigo','item','categoria','presentacion','unidad','almacen_id','almacen','cantidad','cantidad_salida','stock','peso','precio','descuento','total','pendiente_descarga_stock','payload_restaurant'];protected function casts():array{return['cantidad'=>'decimal:4','cantidad_salida'=>'decimal:4','peso'=>'decimal:4','precio'=>'decimal:4','descuento'=>'decimal:4','total'=>'decimal:4','payload_restaurant'=>'array'];}public function guia():BelongsTo{return $this->belongsTo(GuiaInterna::class,'guia_interna_id');}}
